(6069578, 892862, 12733, '<td valign="top">What are the weird reflections in his eyes? The picture would be much better without them.</td>', 'What are the weird reflections in his eyes? The picture would be much better without them.', '2010-06-25 08:49:21.000000', NULL, 1),
(6069579, 893029, 12733, '<td valign="top">Quite a jumble, but it does work. I wouild have liked to have seen the book title clearer - it took some study to make it out.</td>', 'Quite a jumble, but it does work. I wouild have liked to have seen the book title clearer - it took some study to make it out.', '2010-06-25 08:51:15.000000', NULL, 1),
