(6069582, 892965, 12733, '<td valign="top">Sorry, the title doesn''t make the subject a book. There is a challenge called book titles, and this would fit that - but this ain''t it. DNMC</td>', 'Sorry, the title doesn''t make the subject a book. There is a challenge called book titles, and this would fit that - but this ain''t it. DNMC', '2010-06-25 08:53:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6069583, 892953, 12733, '<td valign="top">The background is neither completely plain nor is it close enough to in focus to imply a reader or other meaningful interpretation.</td>', 'The background is neither completely plain nor is it close enough to in focus to imply a reader or other meaningful interpretation.', '2010-06-25 08:54:44.000000', NULL, 1),
(6069584, 892647, 12733, '<td valign="top">Nice study in textures.</td>', 'Nice study in textures.', '2010-06-25 08:55:21.000000', NULL, 1),
(6069585, 893019, 12733, '<td valign="top">What are all those weird highlights? They are more confusing and irritating than meaningful or decorative.</td>', 'What are all those weird highlights? They are more confusing and irritating than meaningful or decorative.', '2010-06-25 08:57:00.000000', NULL, 1),
