(6069588, 893119, 12733, '<td valign="top">Sorry, I don''t go for gimmicks. The books under the chair don''t seem to have a purpose other than to build the title and meet the challenge.</td>', 'Sorry, I don''t go for gimmicks. The books under the chair don''t seem to have a purpose other than to build the title and meet the challenge.', '2010-06-25 09:01:23.000000', NULL, 1),
(6069589, 893009, 12733, '<td valign="top">Does this meet the challenge? Unfortunately I have to say yes, even though I think this is not what a book should look like in my view.</td>', 'Does this meet the challenge? Unfortunately I have to say yes, even though I think this is not what a book should look like in my view.', '2010-06-25 09:03:19.000000', NULL, 1),
(6069591, 892481, 12733, '<td valign="top">Nice statement, well presented. At the same time, I''m not sure this is really progress - books have aesthetic values that an electronic device will never match.</td>', 'Nice statement, well presented. At the same time, I''m not sure this is really progress - books have aesthetic values that an electronic device will never match.', '2010-06-25 09:06:11.000000', NULL, 1),
(6069592, 892948, 117717, '<td valign="top">There''s a tutorial on how to prepare a photo for the challenge- it will help with the sizing</td>', 'There''s a tutorial on how to prepare a photo for the challenge- it will help with the sizing', '2010-06-25 09:06:42.000000', NULL, 1),
(6069593, 893026, 12733, '<td valign="top">A question of photo angle. This one foreshortens the body in a rather unpleasant way, at least to my eyes.</td>', 'A question of photo angle. This one foreshortens the body in a rather unpleasant way, at least to my eyes.', '2010-06-25 09:07:55.000000', NULL, 1),
(6069595, 892854, 12733, '<td valign="top">Very interesting, especially for basic edition. Hope you''ll explain how this was accomplished after the challenge is over.</td>', 'Very interesting, especially for basic edition. Hope you''ll explain how this was accomplished after the challenge is over.', '2010-06-25 09:10:03.000000', NULL, 1),
(6069636, 892854, 76185, '<td valign="top">I think there is an interesting immersed-in-a-book idea here, but this hasn''t quite come together. Superimposing a subject more apropos to the book/title may have been more effective.</td>', 'I think there is an interesting immersed-in-a-book idea here, but this hasn''t quite come together. Superimposing a subject more apropos to the book/title may have been more effective.', '2010-06-25 10:11:12.000000', NULL, 1),
(6069638, 891883, 76185, '<td valign="top">I like the idea of giving movement to the subject but I think having a clearer section in focus could have added to the overall image as this is tending towards the dark-and-blurry end of the spectrum.</td>', 'I like the idea of giving movement to the subject but I think having a clearer section in focus could have added to the overall image as this is tending towards the dark-and-blurry end of the spectrum.', '2010-06-25 10:13:19.000000', NULL, 1),
(6069640, 892800, 76185, '<td valign="top">A good idea to tie in the composition and the book cover but ultimately ends up a little bland and OOF.</td>', 'A good idea to tie in the composition and the book cover but ultimately ends up a little bland and OOF.', '2010-06-25 10:14:17.000000', NULL, 1),
