(6073180, 892907, 83313, '<td valign="top">Just too weird! I love it!</td>', 'Just too weird! I love it!', '2010-06-29 14:23:32.000000', NULL, 1),
(6073185, 892826, 83313, '<td valign="top">Aha, the old strobe-in-the-book trick!</td>', 'Aha, the old strobe-in-the-book trick!', '2010-06-29 14:25:10.000000', NULL, 1),
(6073187, 891883, 70503, '<td valign="top">I really like this concept. This is kind of how I feel when I read...drawn in. The far left side feels a bit empty ...maybe a slightly different crop. Great job!</td>', 'I really like this concept. This is kind of how I feel when I read...drawn in. The far left side feels a bit empty ...maybe a slightly different crop. Great job!', '2010-06-29 14:25:34.000000', NULL, 1),
(6073190, 892402, 70503, '<td valign="top">Pretty funny... I like the concept.</td>', 'Pretty funny... I like the concept.', '2010-06-29 14:26:14.000000', NULL, 1),
(6073192, 892643, 70503, '<td valign="top">The concept is good, but the sky feels too blown out. I am no expert and I do like the idea. Nice job.</td>', 'The concept is good, but the sky feels too blown out. I am no expert and I do like the idea. Nice job.', '2010-06-29 14:26:55.000000', NULL, 1),
(6073193, 892973, 70503, '<td valign="top">love love love the textures! Nice clean image with great focus. Well done!</td>', 'love love love the textures! Nice clean image with great focus. Well done!', '2010-06-29 14:27:24.000000', NULL, 1),
(6073195, 892983, 83313, '<td valign="top">Creative, thought the angle makes it clear this is the subject''s own arm. It actually took me a few moments to realize it was supposed to be coming out of the book, so the illusion did not hold for me. If you''d had a second person to provide the arm coming from an odd angle, that would have been very cool. Still worth a vote on the higher end of the scale, in spite of my nitpick.</td>', 'Creative, thought the angle makes it clear this is the subject''s own arm. It actually took me a few moments to realize it was supposed to be coming out of the book, so the illusion did not hold for me. If you''d had a second person to provide the arm coming from an odd angle, that would have been very cool. Still worth a vote on the higher end of the scale, in spite of my nitpick.', '2010-06-29 14:28:45.000000', NULL, 1),
(6073198, 893026, 83313, '<td valign="top">Watch your JPG compression. I can see some compression artifacts in a few spots, and a 71k file size is more evidence that you used excessive compression. For challenges, always save with the least compression (largest file size) you can and still come in under the challenge limit.</td>', 'Watch your JPG compression. I can see some compression artifacts in a few spots, and a 71k file size is more evidence that you used excessive compression. For challenges, always save with the least compression (largest file size) you can and still come in under the challenge limit.', '2010-06-29 14:32:06.000000', NULL, 1),
(6073201, 892739, 83313, '<td valign="top">I always read the manual before operating a loaded banana. Don''t want any accidents. RTFM, for sure!</td>', 'I always read the manual before operating a loaded banana. Don''t want any accidents. RTFM, for sure!', '2010-06-29 14:35:11.000000', NULL, 1),
(6073208, 892983, 39343, '<td valign="top">Sometime a book really grabs your attention, eh? :)  I really like this except for the bit of torn page - I think that it would have worked better either with that gone and a seamless hole, or else the other way with a really ragged hole, such that the arm exploded out of the book.</td>', 'Sometime a book really grabs your attention, eh? :)  I really like this except for the bit of torn page - I think that it would have worked better either with that gone and a seamless hole, or else the other way with a really ragged hole, such that the arm exploded out of the book.', '2010-06-29 14:44:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6073209, 892283, 39343, '<td valign="top">All kinds of wonderful texture here - great choice on the black and white as well.</td>', 'All kinds of wonderful texture here - great choice on the black and white as well.', '2010-06-29 14:45:08.000000', NULL, 1),
(6073211, 892011, 39343, '<td valign="top">Nicely done overall, although I think that the harsh light on the back cover of the book brings the image down - I find that my eye is drawn there first, as it''s the brightest part of the image.</td>', 'Nicely done overall, although I think that the harsh light on the back cover of the book brings the image down - I find that my eye is drawn there first, as it''s the brightest part of the image.', '2010-06-29 14:46:37.000000', NULL, 1),
(6073212, 893029, 39343, '<td valign="top">I like where you''re going here, but the image is just a bit on the busy side for me - although in some ways I guess that goes along with the story - hmmmm, conflicted....</td>', 'I like where you''re going here, but the image is just a bit on the busy side for me - although in some ways I guess that goes along with the story - hmmmm, conflicted....', '2010-06-29 14:48:02.000000', NULL, 1),
